function configCheck(c){
 if(!['staging','test','production'].includes(c.environment))throw Error('Explicit environment required');
 const u=new URL(c.origin);if(u.pathname!=='/'||u.search||u.hash||u.username)throw Error('Canonical origin required');
 if(!c.otpPepper||c.otpPepper.length<32||!c.staffSecret||c.staffSecret.length<32||c.otpPepper===c.staffSecret)throw Error('Separate strong portal and staff secrets required');
 if(!c.privateDir)throw Error('Private storage required');
 if(c.environment==='production'){
  if(u.protocol!=='https:'||c.isolated||c.smsTransport!=='gateway'||!c.smsGatewayUrl||!c.smsGatewayToken)throw Error('Production requires HTTPS and live configured SMS gateway');
  if(!Array.isArray(c.legalDocuments)||!['privacy','terms','services','personal-data'].every(id=>c.legalDocuments.some(d=>d.document===id&&(id==='privacy'||d.required)))||c.legalDocuments.some(d=>!d.reviewed||d.status==='draft'||typeof d.version!=='string'||!d.version.trim()||d.version.startsWith('draft')||!String(d.title||'').trim()||!String(d.body||'').trim())||new Set(c.legalDocuments.map(d=>d.document)).size!==c.legalDocuments.length)throw Error('Reviewed mandatory legal documents required');
  if(!Number.isInteger(c.smsDailyLimit)||c.smsDailyLimit<1||!Number.isInteger(c.smsBudgetKopecks)||!Number.isInteger(c.smsCostKopecks)||c.smsCostKopecks<1||c.smsBudgetKopecks<c.smsDailyLimit*c.smsCostKopecks)throw Error('Explicit daily SMS spending budget required');
  for(const origin of c.staffOrigins||[]){const su=new URL(origin);if(su.protocol!=='https:'||su.origin!==origin)throw Error('Exact HTTPS staff origin required')}
  if(!c.operator?.legal_name||!c.operator?.inn||!c.operator?.address||!c.operator?.privacy_email)throw Error('Verified operator details required');
 }else if(!c.isolated||c.smsTransport!=='test'||!(['localhost','127.0.0.1','[::1]'].includes(u.hostname)||(c.managedPreview===true&&c.origin==='http://terminal.local:4173'&&process.cwd()==='/site')))throw Error('Test transport is restricted to isolated loopback staging');
}
